begin;
do $$ declare o uuid:='10000000-0000-4000-8000-000000000001'; a uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); r text; t text; op text; denied boolean; n integer; checks integer:=0; tables text[]:=array['care_team_assignments','patient_site_enrollments','staff_site_assignments','restricted_record_flags','restricted_record_opens','advocates','advocate_links','referrals','referral_codes','referral_status_updates','referral_outreach_log','signup_sessions','signup_attempts','signup_safety_scans','identity_review_items','account_support_items','website_inbox_items','intake_checklists','intake_form_status','intake_packet_needs','pre_chart_triage','first_visit_handoffs','staging_imports','staging_rows','packet_documents','on_call_shifts']; begin
insert into public.accounts(id,org_id,kind,synthetic) values(a,o,'staff',true); insert into public.staff_members(id,org_id,account_id,source_key,name,synthetic) values(m,o,a,'phase2_rollback','Fictional Phase2 Rollback',true); for r in select distinct role from app.record_class_grants loop insert into public.staff_role_assignments(org_id,staff_member_id,role) values(o,m,r); end loop;
execute format('create or replace function app.account_id() returns uuid language sql stable security definer set search_path='''' as %L','select '||quote_literal(a::text)||'::uuid'); perform app.attest_beta('en');
for r in select distinct role from app.record_class_grants loop perform app.set_acting_role(r); foreach t in array tables loop foreach op in array array['insert','update','delete'] loop denied:=false; begin execute 'set local role authenticated'; if op='insert' then execute format('insert into public.%I default values',t); elsif op='update' then execute format('update public.%I set updated_at=now() where false',t); else execute format('delete from public.%I where false',t); end if; exception when insufficient_privilege then denied:=true; end; execute 'reset role'; if not denied then raise exception 'phase2_direct_write % % %',r,t,op; end if; checks:=checks+1; end loop; execute 'set local role authenticated'; execute format('select count(*) from public.%I',t) into n; execute 'reset role'; if n<>0 then raise exception 'unexpected_fixture_row % %',r,t; end if; checks:=checks+1; end loop; end loop;
foreach t in array tables loop foreach op in array array['select','insert','update','delete'] loop denied:=false; begin execute 'set local role anon'; execute format('%s public.%I%s',case when op='select' then 'select count(*) from' when op='insert' then 'insert into' when op='update' then 'update' else 'delete from' end,t,case when op='insert' then ' default values' when op='update' then ' set updated_at=now() where false' when op='delete' then ' where false' else '' end); exception when insufficient_privilege then denied:=true; end; execute 'reset role'; if not denied then raise exception 'anon_leak % %',t,op; end if; checks:=checks+1; end loop; end loop;
if checks<>1976 then raise exception 'matrix_count %',checks; end if; end $$; rollback;